import{d as g,C as t,o as d,c as h,a3 as e,E as i,j as a,a as p}from"./chunks/framework.Q4yG9rk_.js";const b=JSON.parse('{"title":"正易心法·第二章","description":"《正易心法》第二章——六画之设非是曲意：以「阴阳运动」对应十二消息卦、以「血气流行」对应脏腑配数，论证六爻重卦是天道与人体的同一节律。","frontmatter":{"title":"正易心法·第二章","description":"《正易心法》第二章——六画之设非是曲意：以「阴阳运动」对应十二消息卦、以「血气流行」对应脏腑配数，论证六爻重卦是天道与人体的同一节律。","category":"guide","aliases":["正易心法第二章","六画之设","阴阳运动血气流行"],"source":["《正易心法》"],"outline":[2,3]},"headers":[],"relativePath":"yijing/zheng-yi-xin-fa/chapter-02.md","filePath":"yijing/zheng-yi-xin-fa/chapter-02.md","lastUpdated":1790647676000}'),u={name:"yijing/zheng-yi-xin-fa/chapter-02.md"},x=g({...u,setup(c){const s=[{id:"z2-01",label:"一、非是曲意",showLabel:!0,sentences:[[{text:"六画",glossary:"liuhua"},"之设，非是",{text:"曲意",glossary:"quyi"},"。"]],note:["六爻重卦的设立，并不是出于人为的刻意安排。（「曲意」即委曲造作之意——不是伏羲「设计」了六十四卦，而是天地人三才的节律本来如此，他只是把它画了出来。）"]},{id:"z2-02",label:"二、阴阳运动",showLabel:!0,sentences:[[{text:"阴阳运动",glossary:"yinyang"},"，若一阳为",{text:"复",glossary:"fu"},"，至六阳为乾，一阴为",{text:"姤",glossary:"gou"},"，至六阴为坤是也。"]],note:["所谓阴阳运动：一阳生为复卦，渐长到六阳为乾卦；一阴生为姤卦，渐长到六阴为坤卦。这就是阴阳的消长——即十二消息卦的次第。"]},{id:"z2-03",label:"三、血气流行",showLabel:!0,sentences:[[{text:"血气流行",glossary:"xueqi"},"，若一六为肾，二为肺，三为脾，四为肝，五为心，"]],note:["所谓血气流行：一与六对应肾，二对应肺，三对应脾，四对应肝，五对应心。这不是随便的配法——「天一生水，地六成之」出自《河图》，水在五行属肾，所以「一六为肾」正是生成数的直接应用。"]},{id:"z2-04",label:"四、始生屯",showLabel:!0,sentences:[["始生",{text:"屯",glossary:"zhun"},"。屯而为",{text:"蒙",glossary:"meng"},"，养蒙为",{text:"需",glossary:"xu"},"之类是也。"]],note:["从这里开始生出屯卦；屯卦发展为蒙卦，养蒙则为需卦，如此之类。这是用生理的节律解释卦序：肾气初动（一六），生命开始，对应屯；接着脾胃（三）运化养育，对应蒙；再往后是饮食滋养，对应需。"]},{id:"z2-05",label:"五、顺此理而已",showLabel:!0,sentences:[["卦画凡以此",{text:"顺此理",glossary:"shunCili"},"而已。"]],note:["卦画的设立，不过是顺应这个道理罢了。（天道与人体的节律本是一理，卦画只是把它如实地画出来。）"]}],o=[{id:"liuhua",term:"六画",pinyin:"liù huà",meaning:"重卦的六爻，即六十四卦每卦的六条爻线。"},{id:"quyi",term:"曲意",pinyin:"qū yì",meaning:"委曲、勉强之意，此处指人为造作、刻意安排。"},{id:"yinyang",term:"阴阳运动",pinyin:"yīn yáng yùn dòng",meaning:"阴阳二气的消长变化，对应十二消息卦的卦序。"},{id:"xueqi",term:"血气流行",pinyin:"xuè qì liú xíng",meaning:"气血在人体中的运行，对应脏腑与卦数的配属。"},{id:"fu",term:"复",pinyin:"fù",meaning:"复卦（一阳在下），十二消息卦之首，冬至一阳生。"},{id:"gou",term:"姤",pinyin:"gòu",meaning:"姤卦（一阴在下），十二消息卦之一，夏至一阴生。"},{id:"zhun",term:"屯",pinyin:"zhūn",meaning:"屯卦，草木初生之象，六十四卦第三卦。"},{id:"meng",term:"蒙",pinyin:"méng",meaning:"蒙卦，童蒙待养之象，六十四卦第四卦。"},{id:"xu",term:"需",pinyin:"xū",meaning:"需卦，等待、饮食之象，六十四卦第五卦。"},{id:"shunCili",term:"顺此理",pinyin:"shùn cǐ lǐ",meaning:"顺应这个道理。强调卦画是自然之理，非人为设计。"}];return(m,n)=>{const r=t("DaoTextReading"),l=t("DaoKeywordCards");return d(),h("div",null,[n[0]||(n[0]=e(`<h1 id="正易心法·第二章" tabindex="-1">正易心法·第二章 <a class="header-anchor" href="#正易心法·第二章" aria-label="Permalink to &quot;正易心法·第二章&quot;">​</a></h1><h2 id="是什么" tabindex="-1">是什么 <a class="header-anchor" href="#是什么" aria-label="Permalink to &quot;是什么&quot;">​</a></h2><p>第二章提出两个<strong>平行命题</strong>，共同指向一个结论：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>阴阳运动  →  十二消息卦  →  天道（宇宙节律）</span></span>
<span class="line"><span>                  ↕</span></span>
<span class="line"><span>血气流行  →  脏腑卦配    →  人道（生命节律）</span></span>
<span class="line"><span>                  ↕</span></span>
<span class="line"><span>         卦画非曲意，乃自然</span></span></code></pre></div><p><strong>核心论点</strong>：六爻重卦不是伏羲「设计」出来的，而是天地人三才的自然节律本来如此，伏羲只是把它「画」了出来。</p><p>这是对第一章「落处」的深化：</p><ul><li>第一章说：要知道卦画的落处；</li><li>第二章说：<strong>落处就在阴阳运动和血气流行之中</strong>。</li></ul><h2 id="为什么重要" tabindex="-1">为什么重要 <a class="header-anchor" href="#为什么重要" aria-label="Permalink to &quot;为什么重要&quot;">​</a></h2><p>这里有一个哲学预设需要挑明：<strong>天人同构</strong>——宇宙的节律和人体的节律是<strong>同一套系统</strong>。</p><p>麻衣把两件事并列（阴阳运动＝天道，血气流行＝人道），暗示它们<strong>不是类比关系，而是同一件事的两个层面</strong>。这个预设的来源：</p><table tabindex="0"><thead><tr><th>来源</th><th>内容</th></tr></thead><tbody><tr><td>《黄帝内经》</td><td>「人与天地相参，与日月相应」</td></tr><tr><td>《系辞传》</td><td>「《易》与天地准，故能弥纶天地之道」</td></tr><tr><td>道家</td><td>「人法地，地法天，天法道，道法自然」</td></tr><tr><td>麻衣此处</td><td>卦画同时描述天道与人体，二者本为一理</td></tr></tbody></table><p>而「一六为肾」之所以成立，来自《河图》：<strong>天一生水，地六成之</strong>——水属肾。这说明麻衣的体系里，<strong>河图、五行、脏腑、卦画是同一套数理的不同表达</strong>，不是各自独立的系统。</p><h2 id="怎么读" tabindex="-1">怎么读 <a class="header-anchor" href="#怎么读" aria-label="Permalink to &quot;怎么读&quot;">​</a></h2><ol><li>先把<strong>十二消息卦</strong>的表自己画一遍（复→乾、姤→坤），这就是「阴阳运动」；</li><li>再看「一六为肾、二为肺……」的配数，回《河图》找依据；</li><li>最后读「始生屯，屯而为蒙，养蒙为需」——<strong>与《序卦传》那种文字推演对比着读</strong>。</li></ol><h2 id="核心内容要点" tabindex="-1">核心内容要点 <a class="header-anchor" href="#核心内容要点" aria-label="Permalink to &quot;核心内容要点&quot;">​</a></h2><ul><li><strong>非曲意</strong>：卦画是自然节律的摹写，不是人为设计。</li><li><strong>阴阳运动</strong>：复→乾（阳长）、姤→坤（阴长），即十二消息卦。</li><li><strong>血气流行</strong>：一六肾、二肺、三脾、四肝、五心。</li><li><strong>河图生成数</strong>：「天一生水，地六成之」——一六配肾的来处。</li><li><strong>卦序即生命过程</strong>：屯（始生）→蒙（养育）→需（饮食）。</li></ul><h2 id="【原典层】原文" tabindex="-1">【原典层】原文 <a class="header-anchor" href="#【原典层】原文" aria-label="Permalink to &quot;【原典层】原文&quot;">​</a></h2>`,17)),i(r,{colophon:"非是曲意 · 阴阳运动 · 血气流行 · 卦序自然",tone:"ink",density:"comfortable","default-mode":"slips","mode-switch":!0,"aria-label":"正易心法第二章原文",sections:s,glossary:o}),n[1]||(n[1]=a("blockquote",null,[a("p",null,"注：本页依所据底本录入，用字随底本，不作统一。原文「一六为肾，二为肺，三为脾，四为肝，五为心」与《黄帝内经》五脏配五行略有出入，是麻衣自己的配法，详见解读层。")],-1)),n[2]||(n[2]=a("h2",{id:"【原典层】字词释义",tabindex:"-1"},[p("【原典层】字词释义 "),a("a",{class:"header-anchor",href:"#【原典层】字词释义","aria-label":'Permalink to "【原典层】字词释义"'},"​")],-1)),i(l,{items:[{term:"曲意",pinyin:["qū","yì"],meaning:"委曲、勉强之意，此处指人为造作、刻意安排。"},{term:"阴阳运动",pinyin:["yīn","yáng"],meaning:"阴阳二气的消长变化，对应十二消息卦的卦序。"},{term:"血气流行",pinyin:["xuè","qì"],meaning:"气血在人体中的运行，对应脏腑与卦数的配属。"},{term:"十二消息卦",pinyin:["shí","èr"],meaning:"复、临、泰、大壮、夬、乾（阳长）；姤、遁、否、观、剥、坤（阴长），以十二卦配十二月。"},{term:"河图生成数",pinyin:["hé","tú"],meaning:"「天一生水，地六成之」等生数与成数相配之说。水属肾，故「一六为肾」。"}]}),n[3]||(n[3]=e('<h2 id="【解读层】三问解读" tabindex="-1">【解读层】三问解读 <a class="header-anchor" href="#【解读层】三问解读" aria-label="Permalink to &quot;【解读层】三问解读&quot;">​</a></h2><h3 id="象-这一章在说什么" tabindex="-1">象：这一章在说什么 <a class="header-anchor" href="#象-这一章在说什么" aria-label="Permalink to &quot;象：这一章在说什么&quot;">​</a></h3><p>两个平行命题，一个结论：</p><ul><li><strong>阴阳运动</strong> → 十二消息卦 → 天道（宇宙节律）</li><li><strong>血气流行</strong> → 脏腑卦配 → 人道（生命节律）</li><li><strong>结论</strong>：卦画非曲意，乃自然</li></ul><p><strong>这是对第一章「落处」的深化</strong>——第一章说要知道卦画的落处，第二章说<strong>落处就在阴阳运动和血气流行之中</strong>。</p><h3 id="理-为什么要这样说" tabindex="-1">理：为什么要这样说 <a class="header-anchor" href="#理-为什么要这样说" aria-label="Permalink to &quot;理：为什么要这样说&quot;">​</a></h3><p>需要挑明的哲学预设是<strong>天人同构</strong>：宇宙的节律与人体的节律<strong>是同一套系统</strong>。麻衣把「阴阳运动」和「血气流行」并列，暗示它们<strong>不是类比，而是同一件事的两个层面</strong>。</p><p>「一六为肾」的来历也值得深究——它来自《河图》：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>天一生水，地六成之 → 水 → 肾（五行：肾属水）→ 一六配肾</span></span></code></pre></div><p><strong>这说明河图、五行、脏腑、卦画在麻衣的体系里是同一套数理的不同表达。</strong></p><h3 id="用-今天怎么进入这一章" tabindex="-1">用：今天怎么进入这一章 <a class="header-anchor" href="#用-今天怎么进入这一章" aria-label="Permalink to &quot;用：今天怎么进入这一章&quot;">​</a></h3><ul><li>把十二消息卦画一遍，看它如何与十二月、与冬至夏至对应；</li><li>「一六为肾」这类的配数，先记住<strong>它出自河图生成数</strong>，不必急着与《内经》对上；</li><li>带着一个问题往下读：<strong>为什么麻衣讲「血气」，而不讲「仁义」？</strong></li></ul><h2 id="【解读层】现代重述" tabindex="-1">【解读层】现代重述 <a class="header-anchor" href="#【解读层】现代重述" aria-label="Permalink to &quot;【解读层】现代重述&quot;">​</a></h2><p>六爻重卦的设立，并不是出于人为的刻意安排，而是阴阳自然运动、血气自然流行的体现。</p><p>所谓阴阳运动：一阳生为复卦，渐长到六阳为乾卦；一阴生为姤卦，渐长到六阴为坤卦——这就是阴阳消长的自然规律。</p><p>所谓血气流行：一与六对应肾，二对应肺，三对应脾，四对应肝，五对应心。</p><p>从这里开始生出屯卦；屯卦发展为蒙卦，养蒙则为需卦，如此之类。</p><p>卦画的设立，不过是顺应这个道理罢了。</p><h2 id="【解读层】我的理解" tabindex="-1">【解读层】我的理解 <a class="header-anchor" href="#【解读层】我的理解" aria-label="Permalink to &quot;【解读层】我的理解&quot;">​</a></h2><blockquote><p><strong>一句话</strong>：第二章只做了一件事——<strong>把「卦画为什么是这样」从文字里搬回到节律里</strong>：往上看是十二消息卦（天），往下看是脏腑配数（人），而两者本是一理。</p></blockquote><p>可以按这几条慢慢写：</p><ul><li><strong>「非是曲意」</strong>——我有没有把某个「本来如此」的东西，误当成谁的设计？</li><li><strong>天人同构</strong>——「人与天地相参」这句话，我是当修辞听，还是当结构看？</li><li><strong>「一六为肾」</strong>——它在《河图》里有出处；我平时遇到不懂的配数，会不会先去疑它「附会」，而不是先找它的落处？</li><li><strong>卦序即生命过程</strong>（屯→蒙→需）——这一层，《序卦传》讲的是「物生必蒙」的道理，麻衣讲的是「肾气初动、脾胃运化」的生理。<strong>同一件事，两套语言。</strong></li><li><strong>留给自己的问题</strong>（承接昇哥的钩子）：麻衣用的是<strong>医家语言</strong>，不是儒家的「仁义礼智」——这说明他理解的《易》，根本上是一门<strong>描述自然运动</strong>的学问，而非道德教化的工具。这与程颐、朱熹用《易》讲修身，是完全不同的路线。<strong>我站哪一边？</strong></li></ul><h2 id="关联" tabindex="-1">关联 <a class="header-anchor" href="#关联" aria-label="Permalink to &quot;关联&quot;">​</a></h2><ul><li><a href="/Dao/yijing/zheng-yi-xin-fa/">正易心法总览</a></li><li><a href="/Dao/yijing/zheng-yi-xin-fa/chapter-01">第一章 · 羲皇易道</a> — 「落处」的深化：落处就在阴阳运动与血气流行之中</li><li><a href="/Dao/yijing/shi-yi/xu-gua-zhuan">序卦传</a> — 同为解释卦序：一以文字义理推演，一以血气节律描述</li><li><a href="/Dao/yijing/shi-yi/xi-ci-zhuan-shang">系辞上传</a> — 「《易》与天地准」是本篇天人同构的直接依据</li></ul>',24))])}}});export{b as __pageData,x as default};
